// 실시간 긴급 게이트 — 4경로. 아래 상수만 본인 상황에 맞게 수정하세요(좁게 유지).
const WHITELIST = ['@cau.ac.kr', 'soobin7612@gmail.com'];   // [경로1] 신뢰 발신자 주소/도메인
const URGENT    = ['마감','오늘까지','긴급','합격','면접','최종','실패','만료']; // [경로1] 긴급 키워드
const BIZ       = ['협업','촬영','섭외','제안','협찬','광고 문의','sponsorship','collaboration']; // [경로2] 비즈니스 기회
const PAY       = ['결제','승인','출금','이체','청구','결제완료','payment','charged']; // [경로3] 결제 신호
const PAY_MIN   = 100000; // [경로3] '큰 금액' 기준(원)
const DEADLINE  = ['마감','기한','까지','신청기간','접수','제출','deadline','due','마감일']; // [경로4] 기한 신호

function isAd(from, subj){
  return /no-?reply|newsletter|beehiiv|mailchimp|substack|mailer|unsubscribe|noreply/i.test(from)
      || /광고|뉴스레터|할인|세일|프로모|무료체험|promo|sale/i.test(subj);
}
function bigAmount(text){
  const re = /(?:₩|\$)\s*([\d,]+)|([\d,]+)\s*(?:원|won)/gi;
  let m; while((m=re.exec(text))){ const n=parseInt((m[1]||m[2]).replace(/,/g,''),10); if(!isNaN(n)&&n>=PAY_MIN) return true; }
  return false;
}
function clean(s){ return ((s||'')+'').replace(/https?:\/\/\S+/g,'').replace(/[\[\]]/g,' ').replace(/[\u200B-\u200D\u2060\uFEFF]/g,'').replace(/\s+/g,' ').trim(); }
function passes(j){
  const from = (((j.from&&j.from.value&&j.from.value[0]&&j.from.value[0].address)||j.from||'')+'').toLowerCase();
  const subjRaw = (j.subject||'')+'';
  const subj = subjRaw.toLowerCase();
  const hay = subjRaw + ' ' + ((j.text||'')+'');
  const ad = isAd(from, subjRaw);
  if (WHITELIST.some(w=>from.includes(w.toLowerCase())) && URGENT.some(k=>subj.includes(k.toLowerCase()))) return true; // 경로1: 신뢰발신+긴급
  if (BIZ.some(k=>subj.includes(k.toLowerCase()))) return true;            // 경로2: 비즈니스 기회 (광고여도 포함 — 국내 협업 메일은 (광고) 표기 의무)
  if (PAY.some(k=>subj.includes(k.toLowerCase())) && bigAmount(hay)) return true; // 경로3: 큰 금액 결제
  if (!ad && DEADLINE.some(k=>subj.includes(k.toLowerCase()))) return true; // 경로4: 기한 있음(광고 아님)
  return false;
}
// 통과 메일에 알림 본문(마크다운) + Gmail 딥링크를 붙여서 넘긴다.
return items.filter((it)=>passes(it.json)).map((it)=>{
  const j = it.json;
  const v = (j.from && j.from.value && j.from.value[0]) || {};
  const name = ((v.name||v.address||'')+'');
  const email = ((v.address||'')+'');
  const subj = (j.subject||'')+'';
  const preview = clean(j.text).slice(0,140);
  const id = ((j.id||j.threadId||'')+'');
  j._gmailLink = id ? ('https://mail.google.com/mail/u/0/#all/'+id) : 'https://mail.google.com/mail/u/0/#inbox';
  j._alertBody = '**'+subj+'**\n'+name+(email?(' <'+email+'>'):'')+(preview?('\n\n'+preview):'');
  return it;
});
